# 设置图表大小
plt.figure(figsize=(16, 8))

# 设置条形图参数
x = np.arange(len(labels))  # 标签位置
width = 0.20  # 条形的宽度，4组数据建议设为0.2左右

# 绘制分组条形图
plt.bar(x - 1.5*width, accuracy_ARN_LSTM_inward, width, label='ARN-LSTM_inward', color='#E63946', edgecolor='black', alpha=0.8)
plt.bar(x - 0.5*width, accuracy_ARN_LSTM_outward, width, label='ARN-LSTM_outward', color='#2A9D8F', edgecolor='black', alpha=0.8)
plt.bar(x + 0.5*width, accuracy_ARN_LSTM_inward_outward, width, label='ARN-LSTM_inward_outward', color='#457B9D', edgecolor='black', alpha=0.8)
plt.bar(x + 1.5*width, ARN_LSTM_fc1_inward_outward, width, label='ARN-LSTM_fc1_inward_outward', color='#A8DADC', edgecolor='black', alpha=0.8)

# 添加图例
plt.legend(loc='upper center', bbox_to_anchor=(0.5, 1.0), ncol=4, fontsize=10, frameon=True)

# 添加标签和标题
plt.xlabel("Action Classes", fontsize=12, fontweight='bold', labelpad=10)
plt.ylabel("Accuracy", fontsize=12, fontweight='bold')
plt.title("NTU RGB+D 120 Dataset (Cross_subject) Action Recognition Performance Comparison", fontsize=14, pad=30)

# 设置x轴刻度，旋转60度以适应较多标签
plt.xticks(ticks=x, labels=labels, rotation=60, ha="right", fontsize=10, color='black')

# 设置y轴范围（根据准确率0-1设置，增加上限给图例留出空间）
plt.ylim(0, 1.1) 
plt.yticks(np.arange(0, 1.1, 0.1))

# 添加水平网格线
